        private void Unload()
        {
            var guidancesystemPlayersToDestroy = new List<GuidanceSystemPlayer>();
            foreach (var entity in BaseNetworkable.serverEntities)
            {
                if (entity != null && !entity.IsDestroyed)
                {
                    var player = entity.GetComponent<GuidanceSystemPlayer>();
                    if (player != null)
                    {
                        guidancesystemPlayersToDestroy.Add(player);
                    }
                }
            }
            foreach (var player in guidancesystemPlayersToDestroy)
            {
                UnityEngine.Object.Destroy(player);
            }

            var rocketsToDestroy = new List<GuidanceSystem>();
            foreach (var entity in BaseNetworkable.serverEntities)
            {
                if (entity != null && !entity.IsDestroyed)
                {
                    var rocket = entity.GetComponent<GuidanceSystem>();
                    if (rocket != null)
                    {
                        rocketsToDestroy.Add(rocket);
                    }
                }
            }
            foreach (var rocket in rocketsToDestroy)
            {
                UnityEngine.Object.Destroy(rocket);
            }
        }
        private void OnPlayerConnected(BasePlayer player)
        {
            if (player == null || !player.userID.Get().IsSteamId() || player.IsNpc) return;
            if (GetPlayer(player) == null)
            {
                DebugLog($"OnPlayerConnected - Adding GuidanceSystemPlayer component to {player.displayName} ({player.UserIDString})");
                player.gameObject.AddComponent<GuidanceSystemPlayer>();
            }
            else
            {
                DebugLog($"OnPlayerConnected - Player {player.displayName} already has GuidanceSystemPlayer component");
            }
        }
        
        // Hook to detect when player equips/unequips items - optimize tracking activation
        private void OnItemHeld(Item item, BasePlayer player)
        {
            if (player == null || !player.userID.Get().IsSteamId() || player.IsNpc) return;
            
            var guidanceComponent = GetPlayer(player);
            if (guidanceComponent == null) return;
            
            // Check if the held item is a rocket launcher (by item ID or type)
            BaseProjectile baseProjectile = item?.GetHeldEntity() as BaseProjectile;
            bool isRocketLauncher = item != null && (
                item.info.itemid == 442886268 || 
                item.info.itemid == -1315992997 || 
                item.info.itemid == 494161326 ||
                baseProjectile is RPGLauncher
            );
            
            if (isRocketLauncher)
            {
                DebugLog($"Player {player.displayName} ({player.UserIDString}) EQUIPPED rocket launcher (ItemID: {item.info.itemid})");
            }
            else if (item != null)
            {
                DebugLog($"Player {player.displayName} ({player.UserIDString}) EQUIPPED other item: {item.info.displayName.english} (ItemID: {item.info.itemid})");
            }
            else
            {
                DebugLog($"Player {player.displayName} ({player.UserIDString}) UNEQUIPPED item (item is null)");
            }
            
            // Update the equipped status in the component
            guidanceComponent.hasRocketLauncherEquipped = isRocketLauncher;
            
            // If not a rocket launcher and tracking is active, stop it
            if (!isRocketLauncher && guidanceComponent.isTrackingActive)
            {
                DebugLog($"Player {player.displayName} - Deactivating tracking (not rocket launcher)");
                guidanceComponent.StopTargetLock(false);
                guidanceComponent.isTrackingActive = false;
            }
            // If it is a rocket launcher, the Update() method will handle activation when aiming starts
        }
        private void OnPlayerDisconnected(BasePlayer player)
        {
            // Destroy all UI elements
            if (player?.net != null)
            {
                CuiHelper.DestroyUi(player, RGTargetDisplay);
                CuiHelper.DestroyUi(player, "RGCenterCrosshair");
                CuiHelper.DestroyUi(player, "RGCornerTL");
                CuiHelper.DestroyUi(player, "RGCornerTR");
                CuiHelper.DestroyUi(player, "RGCornerBL");
                CuiHelper.DestroyUi(player, "RGCornerBR");
                CuiHelper.DestroyUi(player, "RGStatusPanel");
                CuiHelper.DestroyUi(player, "RGStatusText");
                CuiHelper.DestroyUi(player, "RGInfoPanel");
                CuiHelper.DestroyUi(player, "RGTargetName");
                CuiHelper.DestroyUi(player, "RGDistance");
                
                // Also destroy via CommunityEntity RPC
                var communityEntity = CommunityEntity.ServerInstance;
                if (communityEntity != null)
                {
                    var destroyData = Pool.Get<List<object>>();
                    destroyData.Add(new { destroyUi = "RGCenterCrosshair" });
                    destroyData.Add(new { destroyUi = "RGCornerTL" });
                    destroyData.Add(new { destroyUi = "RGCornerTR" });
                    destroyData.Add(new { destroyUi = "RGCornerBL" });
                    destroyData.Add(new { destroyUi = "RGCornerBR" });
                    destroyData.Add(new { destroyUi = "RGStatusPanel" });
                    destroyData.Add(new { destroyUi = "RGInfoPanel" });
                    communityEntity.ClientRPC(RpcTarget.Player("AddUI", player.net.connection), JsonConvert.SerializeObject(destroyData));
                    Pool.FreeUnmanaged(ref destroyData);
                }
            }
            
            GuidanceSystemPlayer guidancesystemPlayer = GetPlayer(player);
            if (guidancesystemPlayer != null)
            {
                UnityEngine.Object.Destroy(guidancesystemPlayer);
            }
        }
        private void OnRocketLaunched(BasePlayer player, BaseEntity entity)
        {
            if (player == null) return;
            GuidanceSystemPlayer guidancesystemPlayer = GetPlayer(player);
            if (guidancesystemPlayer == null) return;
            if (!guidancesystemPlayer.TargetLocked) return;

            // Adjust speed and gravity
            ServerProjectile serverProjectile = entity.GetComponent<ServerProjectile>();
            if (serverProjectile == null) return;

            serverProjectile.gravityModifier = 0f;
            serverProjectile.speed += serverProjectile.speed * config.rocketsettings.speed;

            // Adjust damage
            TimedExplosive timedExplosive = entity.GetComponent<TimedExplosive>();
            if (timedExplosive == null) return;

            foreach (DamageTypeEntry damageType in timedExplosive.damageTypes)
            {
                int amount = GetDamageAmount(entity);
                damageType.amount += (float)amount;
            }

            // Set fuse and explosion effect
            timedExplosive.SetFuse(config.rocketsettings.detonate);
            timedExplosive.explosionEffect.guid = string.Empty;

            // Initialize guidance system
            GuidanceSystem rocket = entity.gameObject.AddComponent<GuidanceSystem>();
            rocket.Initialize(guidancesystemPlayer.Target, player);
            guidancesystemPlayer.StopTargetLock(false);
        }
