        private const string RGTargetDisplay = "RGTargetDisplay";
        private const string RGTargetData = "RGTargetData";
        // Images
        private const string RGCrosshair = "crosshair";
        #endregion

        #region UI
        // UI methods removed - now using CommunityEntity UI system
        #endregion

        #region Lang
        protected override void LoadDefaultMessages()
        {
            lang.RegisterMessages(new Dictionary<string, string>
            {
                ["targetname"] = "Target",
                ["targetdistance"] = "Distance",
                ["targetdistancemax"] = "max",
                ["lockpending"] = "PENDING (HOLD)",
                ["lockfailed"] = "FAILED (HOLD)",
                ["locked"] = "LOCKED (FIRE)",
                ["lock"] = "Lock",
            }, this);
        }
        private string RGTLang(string key, string id = null, params object[] args) => string.Format(lang.GetMessage(key, this, id), args);
        #endregion
